import { createGoogleGenerativeAI } from "@ai-sdk/google";
import { streamText } from "ai";
import { GoogleAIModels } from "../types/index.js";
import { BaseProvider } from "../core/baseProvider.js";
import { logger } from "../utils/logger.js";
import { createTimeoutController, TimeoutError } from "../utils/timeout.js";
import { AuthenticationError, NetworkError, ProviderError, RateLimitError, } from "../types/errors.js";
import { DEFAULT_MAX_STEPS } from "../core/constants.js";
import { streamAnalyticsCollector } from "../core/streamAnalytics.js";
import { buildMessagesArray, buildMultimodalMessagesArray, convertToCoreMessages, } from "../utils/messageBuilder.js";
import { buildMultimodalOptions } from "../utils/multimodalOptionsBuilder.js";
// Google AI Live API types now imported from ../types/providerSpecific.js
// Import proper types for multimodal message handling
// Create Google GenAI client
async function createGoogleGenAIClient(apiKey) {
    const mod = await import("@google/genai");
    const ctor = mod.GoogleGenAI;
    if (!ctor) {
        throw new Error("@google/genai does not export GoogleGenAI");
    }
    const Ctor = ctor;
    return new Ctor({ apiKey });
}
// Environment variable setup
if (!process.env.GOOGLE_GENERATIVE_AI_API_KEY &&
    process.env.GOOGLE_AI_API_KEY) {
    process.env.GOOGLE_GENERATIVE_AI_API_KEY = process.env.GOOGLE_AI_API_KEY;
}
/**
 * Google AI Studio provider implementation using BaseProvider
 * Migrated from original GoogleAIStudio class to new factory pattern
 */
export class GoogleAIStudioProvider extends BaseProvider {
    constructor(modelName, sdk) {
        super(modelName, "google-ai", sdk);
        logger.debug("GoogleAIStudioProvider initialized", {
            model: this.modelName,
            provider: this.providerName,
            sdkProvided: !!sdk,
        });
    }
    // ===================
    // ABSTRACT METHOD IMPLEMENTATIONS
    // ===================
    getProviderName() {
        return "google-ai";
    }
    getDefaultModel() {
        return process.env.GOOGLE_AI_MODEL || GoogleAIModels.GEMINI_2_5_FLASH;
    }
    /**
     * 🔧 PHASE 2: Return AI SDK model instance for tool calling
     */
    getAISDKModel() {
        const apiKey = this.getApiKey();
        const google = createGoogleGenerativeAI({ apiKey });
        return google(this.modelName);
    }
    handleProviderError(error) {
        if (error instanceof TimeoutError) {
            throw new NetworkError(error.message, this.providerName);
        }
        const errorRecord = error;
        const message = typeof errorRecord?.message === "string"
            ? errorRecord.message
            : "Unknown error";
        if (message.includes("API_KEY_INVALID")) {
            throw new AuthenticationError("Invalid Google AI API key. Please check your GOOGLE_AI_API_KEY environment variable.", this.providerName);
        }
        if (message.includes("RATE_LIMIT_EXCEEDED")) {
            throw new RateLimitError("Google AI rate limit exceeded. Please try again later.", this.providerName);
        }
        throw new ProviderError(`Google AI error: ${message}`, this.providerName);
    }
    // executeGenerate removed - BaseProvider handles all generation with tools
    async executeStream(options, _analysisSchema) {
        // Phase 1: if audio input present, bridge to Gemini Live (Studio) using @google/genai
        if (options.input?.audio) {
            return await this.executeAudioStreamViaGeminiLive(options);
        }
        this.validateStreamOptions(options);
        const startTime = Date.now();
        const apiKey = this.getApiKey();
        // Ensure environment variable is set for @ai-sdk/google
        if (!process.env.GOOGLE_GENERATIVE_AI_API_KEY) {
            process.env.GOOGLE_GENERATIVE_AI_API_KEY = apiKey;
        }
        const model = await this.getAISDKModelWithMiddleware(options);
        const timeout = this.getTimeout(options);
        const timeoutController = createTimeoutController(timeout, this.providerName, "stream");
        try {
            // Get tools consistently with generate method
            const shouldUseTools = !options.disableTools && this.supportsTools();
            const tools = shouldUseTools ? await this.getAllTools() : {};
            // Build message array from options with multimodal support
            const hasMultimodalInput = !!(options.input?.images?.length ||
                options.input?.content?.length ||
                options.input?.files?.length ||
                options.input?.csvFiles?.length ||
                options.input?.pdfFiles?.length);
            let messages;
            if (hasMultimodalInput) {
                logger.debug(`Google AI Studio: Detected multimodal input, using multimodal message builder`, {
                    hasImages: !!options.input?.images?.length,
                    imageCount: options.input?.images?.length || 0,
                    hasContent: !!options.input?.content?.length,
                    contentCount: options.input?.content?.length || 0,
                });
                const multimodalOptions = buildMultimodalOptions(options, this.providerName, this.modelName);
                const mm = await buildMultimodalMessagesArray(multimodalOptions, this.providerName, this.modelName);
                // Convert multimodal messages to Vercel AI SDK format (CoreMessage[])
                messages = convertToCoreMessages(mm);
            }
            else {
                logger.debug(`Google AI Studio: Text-only input, using standard message builder`);
                messages = await buildMessagesArray(options);
            }
            const result = await streamText({
                model,
                messages: messages,
                temperature: options.temperature,
                maxTokens: options.maxTokens, // No default limit - unlimited unless specified
                tools,
                maxSteps: options.maxSteps || DEFAULT_MAX_STEPS,
                toolChoice: shouldUseTools ? "auto" : "none",
                abortSignal: timeoutController?.controller.signal,
                experimental_telemetry: this.getStreamTelemetryConfig(options),
                onStepFinish: ({ toolCalls, toolResults }) => {
                    this.handleToolExecutionStorage(toolCalls, toolResults, options, new Date()).catch((error) => {
                        logger.warn("[GoogleAiStudioProvider] Failed to store tool executions", {
                            provider: this.providerName,
                            error: error instanceof Error ? error.message : String(error),
                        });
                    });
                },
            });
            timeoutController?.cleanup();
            // Transform string stream to content object stream using BaseProvider method
            const transformedStream = this.createTextStream(result);
            // Create analytics promise that resolves after stream completion
            const analyticsPromise = streamAnalyticsCollector.createAnalytics(this.providerName, this.modelName, result, Date.now() - startTime, {
                requestId: `google-ai-stream-${Date.now()}`,
                streamingMode: true,
            });
            return {
                stream: transformedStream,
                provider: this.providerName,
                model: this.modelName,
                analytics: analyticsPromise,
                metadata: {
                    startTime,
                    streamId: `google-ai-${Date.now()}`,
                },
            };
        }
        catch (error) {
            timeoutController?.cleanup();
            throw this.handleProviderError(error);
        }
    }
    // ===================
    // HELPER METHODS
    // ===================
    async executeAudioStreamViaGeminiLive(options) {
        const startTime = Date.now();
        const apiKey = this.getApiKey();
        // Dynamic import to avoid hard dependency unless audio streaming is used
        let client;
        try {
            client = await createGoogleGenAIClient(apiKey);
        }
        catch {
            throw new AuthenticationError("Missing '@google/genai'. Install with: pnpm add @google/genai", this.providerName);
        }
        const model = this.modelName ||
            process.env.GOOGLE_VOICE_AI_MODEL ||
            "gemini-2.5-flash-preview-native-audio-dialog";
        const queue = [];
        let resolveNext = null;
        let done = false;
        const push = (item) => {
            if (done) {
                return;
            }
            if (item.type === "audio") {
                if (resolveNext) {
                    const fn = resolveNext;
                    resolveNext = null;
                    fn({ value: { type: "audio", audio: item.audio }, done: false });
                    return;
                }
            }
            queue.push(item);
        };
        const session = await client.live.connect({
            model,
            callbacks: {
                onopen: () => {
                    // no-op
                },
                onmessage: async (message) => {
                    try {
                        const audio = message?.serverContent?.modelTurn?.parts?.[0]?.inlineData;
                        if (audio?.data) {
                            const buf = Buffer.from(String(audio.data), "base64");
                            const chunk = {
                                data: buf,
                                sampleRateHz: 24000,
                                channels: 1,
                                encoding: "PCM16LE",
                            };
                            push({ type: "audio", audio: chunk });
                        }
                        if (message?.serverContent?.interrupted) {
                            // allow consumer to handle; no special action required here
                        }
                    }
                    catch (e) {
                        push({ type: "error", error: e });
                    }
                },
                onerror: (e) => {
                    push({ type: "error", error: e });
                },
                onclose: (_e) => {
                    push({ type: "end" });
                },
            },
            config: {
                responseModalities: ["AUDIO"],
                speechConfig: {
                    voiceConfig: { prebuiltVoiceConfig: { voiceName: "Orus" } },
                },
            },
        });
        // Feed upstream audio frames concurrently
        (async () => {
            try {
                const spec = options.input?.audio;
                if (!spec) {
                    logger.debug("[GeminiLive] No audio spec found on input; skipping upstream send");
                    return;
                }
                for await (const frame of spec.frames) {
                    // Zero-length frame acts as a 'flush' control signal
                    if (!frame || frame.byteLength === 0) {
                        try {
                            if (session.sendInput) {
                                await session.sendInput({ event: "flush" });
                            }
                            else if (session.sendRealtimeInput) {
                                await session.sendRealtimeInput({ event: "flush" });
                            }
                        }
                        catch (err) {
                            logger.debug("[GeminiLive] flush control failed (non-fatal)", {
                                error: err instanceof Error ? err.message : String(err),
                            });
                        }
                        continue;
                    }
                    // Convert PCM16LE buffer to base64 and wrap in genai Blob-like object
                    const base64 = frame.toString("base64");
                    const mimeType = `audio/pcm;rate=${spec.sampleRateHz || 16000}`;
                    await session.sendRealtimeInput?.({
                        media: { data: base64, mimeType },
                    });
                }
                // Best-effort flush signal if supported
                try {
                    if (session.sendInput) {
                        await session.sendInput({ event: "flush" });
                    }
                    else if (session.sendRealtimeInput) {
                        await session.sendRealtimeInput({ event: "flush" });
                    }
                }
                catch (err) {
                    logger.debug("[GeminiLive] final flush failed (non-fatal)", {
                        error: err instanceof Error ? err.message : String(err),
                    });
                }
            }
            catch (e) {
                push({ type: "error", error: e });
            }
        })().catch(() => {
            // ignore
        });
        // AsyncIterable for stream events
        const asyncIterable = {
            [Symbol.asyncIterator]() {
                return {
                    async next() {
                        if (queue.length > 0) {
                            const item = queue.shift();
                            if (!item) {
                                return {
                                    value: undefined,
                                    done: true,
                                };
                            }
                            if (item.type === "audio") {
                                return {
                                    value: { type: "audio", audio: item.audio },
                                    done: false,
                                };
                            }
                            if (item.type === "end") {
                                done = true;
                                return {
                                    value: undefined,
                                    done: true,
                                };
                            }
                            if (item.type === "error") {
                                done = true;
                                throw item.error instanceof Error
                                    ? item.error
                                    : new Error(String(item.error));
                            }
                        }
                        if (done) {
                            return {
                                value: undefined,
                                done: true,
                            };
                        }
                        return await new Promise((resolve) => {
                            resolveNext = resolve;
                        });
                    },
                };
            },
        };
        return {
            stream: asyncIterable,
            provider: this.providerName,
            model: model,
            metadata: {
                startTime,
                streamId: `google-ai-audio-${Date.now()}`,
            },
        };
    }
    getApiKey() {
        const apiKey = process.env.GOOGLE_AI_API_KEY || process.env.GOOGLE_GENERATIVE_AI_API_KEY;
        if (!apiKey) {
            throw new AuthenticationError("GOOGLE_AI_API_KEY or GOOGLE_GENERATIVE_AI_API_KEY environment variable is not set", this.providerName);
        }
        return apiKey;
    }
}
export default GoogleAIStudioProvider;
